  FOREIGN KEY ("tenant", "canonical") REFERENCES canonical_record ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision") REFERENCES decision_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "option") REFERENCES decision_option ("tenant", "id")
);

CREATE TABLE survivorship_decision (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "resolution" TEXT COLLATE "C" NOT NULL,
  "choice" TEXT COLLATE "C" NOT NULL,
  "canonical" TEXT COLLATE "C" NOT NULL,
  "decision" TEXT COLLATE "C" NOT NULL,
  "outcome" TEXT COLLATE "C" NOT NULL,
  "terminal" TEXT COLLATE "C" NOT NULL,
  "option" TEXT COLLATE "C" NOT NULL,
  "lineage" TEXT COLLATE "C" NOT NULL,
  "source_node" TEXT COLLATE "C" NOT NULL,
  "target_node" TEXT COLLATE "C" NOT NULL,
  "source" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "resolution") REFERENCES resolution_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "choice") REFERENCES resolution_choice ("tenant", "id"),
  FOREIGN KEY ("tenant", "canonical") REFERENCES canonical_record ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision") REFERENCES decision_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "outcome") REFERENCES decision_outcome ("tenant", "id"),
  FOREIGN KEY ("tenant", "terminal") REFERENCES decision_event ("tenant", "id"),
  FOREIGN KEY ("tenant", "option") REFERENCES decision_option ("tenant", "id"),
  FOREIGN KEY ("tenant", "lineage") REFERENCES lineage_relation ("tenant", "id"),
  FOREIGN KEY ("tenant", "source_node") REFERENCES lineage_node ("tenant", "id"),
  FOREIGN KEY ("tenant", "target_node") REFERENCES lineage_node ("tenant", "id"),
  FOREIGN KEY ("tenant", "source") REFERENCES source_record ("tenant", "id")
);

CREATE TABLE canonical_link (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "source" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "previous" TEXT COLLATE "C",
  "canonical" TEXT COLLATE "C" NOT NULL,
  "from_" TEXT COLLATE "C",
  "kind" TEXT COLLATE "C" NOT NULL,
  "survivorship" TEXT COLLATE "C",
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "source") REFERENCES source_record ("tenant", "id"),
  FOREIGN KEY ("tenant", "previous") REFERENCES canonical_link ("tenant", "id"),
  FOREIGN KEY ("tenant", "canonical") REFERENCES canonical_record ("tenant", "id"),
  FOREIGN KEY ("tenant", "from_") REFERENCES canonical_record ("tenant", "id"),
  FOREIGN KEY ("tenant", "survivorship") REFERENCES survivorship_decision ("tenant", "id")
);

